import pandas as pd
import networkx as nx
import matplotlib.pyplot as plt
from matplotlib.colors import LinearSegmentedColormap

# Path to the CSV file (adjust as needed)
file_path = 'Profiles_transition.csv'

# Read the CSV file with the correct separator and handle spaces
data = pd.read_csv(file_path, sep=';', engine='python')

# Remove the first column by its index (index 0)
transitions = data.drop(data.columns[0], axis=1)

# Clean columns that may contain unwanted spaces
transitions['Probability_profiles'] = transitions['Probability_profiles'].str.replace(' ', '')  # Remove spaces
transitions['Probability_profiles'] = transitions['Probability_profiles'].str.replace(',', '.')  # Replace commas with dots
transitions['Probability_profiles'] = transitions['Probability_profiles'].astype(float)  # Convert to float

# Remove rows where Probability_state == 0
transitions = transitions[transitions['Probability_profiles'] > 0]

# Ensure the required columns exist
if 'From' not in transitions.columns or 'To' not in transitions.columns:
    raise ValueError("The columns 'From' or 'To' are missing from the DataFrame transitions.")

# Create a directed graph
G = nx.DiGraph()

# Add nodes and edges with weights to the graph (including self-loops)
for row in transitions.itertuples(index=False):
    source, target, probability = row.From, row.To, row.Probability_profiles
    G.add_edge(source, target, weight=probability)

# Define node positions with greater separation
pos = {
    "A": (0, 2),
    "B": (0.5, 2),
    "C": (0, 0),
    "D": (0.5, 0),
    "E": (-0.25, 1),
    "F": (0.75, 1)
}

# Define colors for nodes
node_colors = {
    "C": '#66c2a5',  # Green
    "B": '#e0c900',  # Dark yellow
    "A": '#8da0cb',  # Blue
    "F": '#e78ac3',  # Pink
    "E": '#a6d854',  # Light green
    "D": '#fc8d62'   # Dark orange
}

# Assign node colors based on labels
node_color_list = [node_colors.get(node, '#000000') for node in G.nodes]

# Plot the graph
plt.figure(figsize=(12, 8))
edges = G.edges(data=True)

# Draw nodes with defined colors
nx.draw_networkx_nodes(G, pos, node_size=1200, node_color=node_color_list)

# Draw node labels
nx.draw_networkx_labels(G, pos, font_size=16, font_weight='bold')

# Dictionnaire : nœud → (texte personnalisé, position x, position y)
node_annotations = {
    "A": ("No pathogen", -0.32, 1.95),
    "B": ("NAS", 0.61, 1.95),
    "C": ("C. bovis \nS. uberis", -0.2, -0.2),
    "D": ("C. bovis", 0.58, -0.1),
    "E": ("S. uberis", -0.5, 0.9),
    "F": ("T.pyo./P.indo. \nand/or \nyeasts", 0.8, 0.74)
}

# Ajouter une annotation colorée à chaque nœud, avec texte et position personnalisés
for node, (label_text, x, y) in node_annotations.items():
    color = node_colors.get(node, '#000000')
    
    plt.text(
        x, y,
        label_text,
        fontsize=12,
        color=color,
        fontweight='bold'
    )

# Normalize weights for color mapping
weights = [data['weight'] for _, _, data in edges]
max_weight = max(weights)

import matplotlib.colors as mcolors
# Liste des couleurs du gris clair (#cccccc) au noir (#000000)
grey_to_black = ['#cccccc', '#999999', '#666666', '#333333', '#000000']

# Créer un colormap continu
cmap = mcolors.LinearSegmentedColormap.from_list('grey_to_black', grey_to_black, N=256)

# Normalize weights for color mapping
norm = plt.Normalize(vmin=min(weights), vmax=max(weights))

# Draw curved edges with arrows colored based on weight, including self-loops
ax = plt.gca()
for u, v, data in edges:
    weight = data['weight'] * 15  # Increase edge thickness
    color = cmap(norm(data['weight']))
    
    # Use larger curvature radius for self-loops
    rad = 0.5 if u == v else 0.3
    
    nx.draw_networkx_edges(
        G, pos, edgelist=[(u, v)], arrowstyle='-|>', arrowsize=30, edge_color=[color],
        connectionstyle=f'arc3,rad={rad}', width=weight, ax=ax, node_size=800
    )

# Add a color bar to show the weight scale
sm = plt.cm.ScalarMappable(cmap=cmap, norm=norm)
sm.set_array([])
plt.colorbar(sm, ax=plt.gca(), label='Transition weights')

plt.title("")
plt.axis('off')  # Hide axes

# Save the graph as an image file
output_path = 'Figure_6.png'
plt.savefig(output_path, format='png', dpi=300)
